178	    /// Returns rules
179	    pub fn as_rules(&self, path: &Path) -> Option<Rules> {
180	        let overrides = &self.override_settings;
181	        self.linter
182	            .rules
183	            .as_ref()
184	            .map(|rules| overrides.override_as_rules(path, rules.clone()))
185	    }
186	}
