13	/// A data structure to use when there's need to match a string or a path a against
14	/// a unix shell style patterns
15	#[derive(Debug)]
16	pub struct Matcher {
17	    root: Option<PathBuf>,
18	    git_ignore: Option<Gitignore>,
19	    patterns: Vec<Pattern>,
20	    options: MatchOptions,
21	    /// Whether the string was already checked
22	    already_checked: RwLock<HashMap<String, bool>>,
23	}
24	
25	impl Matcher {
26	    /// Creates a new Matcher with given options.
27	    ///
28	    /// Check [glob website](https://docs.rs/glob/latest/glob/struct.MatchOptions.html) for [MatchOptions]
29	    pub fn new(options: MatchOptions) -> Self {
30	        Self {
31	            root: None,
32	            git_ignore: None,
33	            patterns: Vec::new(),
34	            options,
35	            already_checked: RwLock::new(HashMap::default()),
36	        }
37	    }
38	
39	    pub fn empty() -> Self {
40	        Self {
41	            root: None,
42	            git_ignore: None,
43	            patterns: Vec::new(),
44	            options: MatchOptions::default(),
45	            already_checked: RwLock::new(HashMap::default()),
46	        }
47	    }
48	
49	    pub fn set_root(&mut self, root: PathBuf) {
50	        self.root = Some(root);
51	    }
52	
53	    pub fn add_gitignore_matches(
54	        &mut self,
55	        path: PathBuf,
56	        matches: &[String],
57	    ) -> Result<(), WorkspaceError> {
58	        let mut gitignore_builder = GitignoreBuilder::new(path.clone());
59	
60	        for the_match in matches {
61	            gitignore_builder
62	                .add_line(Some(path.clone()), the_match)
63	                .map_err(|err| {
64	                    WorkspaceError::Configuration(ConfigurationDiagnostic::InvalidIgnorePattern(
65	                        InvalidIgnorePattern {
66	                            message: err.to_string(),
67	                        },
68	                    ))
69	                })?;
70	        }
71	        let gitignore = gitignore_builder.build().map_err(|err| {
72	            WorkspaceError::Configuration(ConfigurationDiagnostic::InvalidIgnorePattern(
73	                InvalidIgnorePattern {
74	                    message: err.to_string(),
75	                },
76	            ))
77	        })?;
78	        self.git_ignore = Some(gitignore);
79	
80	        Ok(())
81	    }
