83	    /// It adds a unix shell style pattern
84	    pub fn add_pattern(&mut self, pattern: &str) -> Result<(), PatternError> {
85	        let pattern = Pattern::new(pattern)?;
86	        self.patterns.push(pattern);
87	        Ok(())
